mapper.select:
SELECT re.plan_id, re.plan_name, re.plan_type, re.patrol_interval, re.if_auto_execute, re.plan_start_time, re.plan_end_time, re.user_code, re.tenant_id, re.creator_date, re.modifier_date, u.user_name creator, re.modifier FROM vm_reserve_plan_t re left join sys_user u on re.user_code = u.user_id WHERE re.delete_flag = '0' and re.tenant_id = #{tenantId} and (re.plan_type = 1 or (re.plan_type = 2 and re.user_code = #{userId} )) and industry_code = #{industryCode}
and re.plan_name like concat ('%',#{reservePlanDTO.planName},'%')
and re.plan_type = #{reservePlanDTO.planType}
and u.user_name like concat ('%',#{reservePlanDTO.creator},'%')
and re.modifier like concat ('%',#{reservePlanDTO.modifier},'%')
AND re.creator_date >= #{reservePlanDTO.creatorDateStart} AND re.creator_date <= #{reservePlanDTO.creatorDateEnd}
AND re.modifier_date >= #{reservePlanDTO.modifierDateStart} AND re.modifier_date <= #{reservePlanDTO.modifierDateEnd}
ORDER BY creator_date desc

select count(1) from vm_reserve_plan_t where delete_flag = '0'

    and plan_id != #{planId}


    and plan_name = #{planName}


    and user_code = #{userCode}


    and industry_code = #{industryCode}


    and tenant_id = #{tenantId}


    and plan_type = #{planType}
